// src/app/api/spots/route.ts
import { NextResponse } from "next/server";
import { prisma } from "@/lib/prisma";

const WEATHER_OPTIONS = ["晴れ", "曇り", "小雨", "雨", "雪"] as const;
type WeatherLabel = (typeof WEATHER_OPTIONS)[number];

// URL / メール検出（ゆるめに弾く）
const URL_LIKE = /(https?:\/\/|www\.)/i;
const EMAIL_LIKE = /[a-z0-9._%+-]+@[a-z0-9.-]+\.[a-z]{2,}/i;

function commentHasForbidden(content: string) {
  const s = (content || "").trim();
  if (!s) return false;
  return URL_LIKE.test(s) || EMAIL_LIKE.test(s);
}

export async function POST(req: Request) {
  try {
    const body = await req.json();

    const place = String(body.place ?? "").trim();
    const bloom = Number(body.bloom); // 0..6
    const weather = String(body.weather ?? "").trim() as WeatherLabel;
    const comment = body.comment ? String(body.comment) : null;

    const imageUrl = body.imageUrl ? String(body.imageUrl) : null; // /uploads/xxx.jpg
    const imageHash = body.imageHash ? String(body.imageHash) : null; // uploadで返すhash

    if (!place) {
      return NextResponse.json({ ok: false, error: "place is required" }, { status: 400 });
    }
    if (!Number.isInteger(bloom) || bloom < 0 || bloom > 6) {
      return NextResponse.json({ ok: false, error: "invalid bloom" }, { status: 400 });
    }
    if (!WEATHER_OPTIONS.includes(weather)) {
      return NextResponse.json({ ok: false, error: "invalid weather" }, { status: 400 });
    }

    // ✅ コメント防犯：URL/メール禁止
    if (comment && commentHasForbidden(comment)) {
      return NextResponse.json(
        { ok: false, error: "コメントにURLやメールアドレスは入力できません" },
        { status: 400 }
      );
    }

    if (imageUrl && !imageUrl.startsWith("/uploads/")) {
      return NextResponse.json({ ok: false, error: "invalid imageUrl" }, { status: 400 });
    }

    // 画像があるなら hash も必須（多重投稿防止のため）
    if (imageUrl && !imageHash) {
      return NextResponse.json(
        { ok: false, error: "imageHash is required when imageUrl is set" },
        { status: 400 }
      );
    }

    try {
      const created = await prisma.spot.create({
        data: {
          place,
          bloom,
          weather,
          comment,
          imageUrl,
          imageHash,
        },
      });

      return NextResponse.json({ ok: true, id: created.id });
    } catch (e: any) {
      if (String(e?.code) === "P2002") {
        return NextResponse.json(
          { ok: false, error: "同じ画像はすでに投稿されています" },
          { status: 409 }
        );
      }
      throw e;
    }
  } catch {
    return NextResponse.json({ ok: false, error: "Failed to create spot" }, { status: 400 });
  }
}